c6-4.solution:
#include <stdio.h>

int main(void) {
    int x, sum = 0;
    while (scanf("%d", &x) == 1) {
        if (x == 0) { break; }
        sum += x;
    }
    printf("%d\n", sum);
    return 0;
}

