c6-5.solution:
#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) { return 1; }
    for (int i = 1; i <= n; i++) {
        if (i % 3 == 0) { continue; }
        printf("%d ", i);
    }
    printf("\n");
    return 0;
