c6-8.solution:
#include <stdio.h>

int main(void) {
    int limit, k = 0;
    if (scanf("%d", &limit) != 1) { return 1; }
    while (1) {
        if (2 * k >= limit) { break; }
        k++;
    }
    printf("%d\n", k);
    return 0;
}

